// W14 · cuenta CITAS AGENDADAS de la semana (OP·Bot Venttur).
// ⚠ Métrica definitiva a confirmar con el cliente (etapas que cuentan + createdAt vs cambio-de-etapa).
const opps = $('GHL Query OP·Bot').all().flatMap(i => (i.json && i.json.opportunities) || []);
const BOOKED = ['36fa419c-e836-48a8-8a77-72b38d357173','7c0c40b6-4a25-4d1c-a2a2-40e5f38095bc','08f742d9-2aaa-4a76-abc2-48d34a9f3ba9'];
const now = Date.now(); const WEEK = 7*864e5;
const fecha = (o) => Date.parse(o.lastStageChangeAt || o.createdAt || '') || 0;
const citas = opps.filter(o => BOOKED.includes(o.pipelineStageId) && (now - fecha(o)) <= WEEK && fecha(o) > 0);
const n = citas.length;
const d0 = new Date(now - WEEK).toISOString().slice(0,10);
const d1 = new Date(now).toISOString().slice(0,10);
const semana = d0 + ' → ' + d1;
const html = `<!DOCTYPE html><html><body style="margin:0;font-family:Arial,Helvetica,sans-serif;background:#0d0a1f;padding:24px"><div style="max-width:520px;margin:0 auto;background:#ffffff;border-radius:12px;overflow:hidden"><div style="height:6px;background:#7c3aed"></div><div style="padding:28px"><h2 style="color:#0d0a1f;margin:0 0 4px">Resumen semanal Venttur</h2><p style="color:#888;margin:0 0 20px;font-size:13px">Semana ${semana}</p><div style="background:#f5f3ff;border-radius:10px;padding:24px;text-align:center"><div style="font-size:46px;font-weight:800;color:#7c3aed;line-height:1">${n}</div><div style="color:#333;font-size:15px;margin-top:4px">citas agendadas</div></div></div><div style="background:#0d0a1f;color:#a78bfa;padding:14px;text-align:center;font-size:12px">la agencia</div></div></body></html>`;
return [{ json: { citas_agendadas: n, semana, html, subject: `📊 Resumen semanal Venttur — ${n} citas agendadas` } }];
